import{_ as l,o as i,c as t,a2 as r}from"./chunks/framework.DDY-poMm.js";const p=JSON.parse('{"title":"交易品类说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/trading.md","filePath":"zh/guide/trading.md","lastUpdated":1790683574000}'),e={name:"zh/guide/trading.md"};function o(s,a,n,d,h,c){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="交易品类说明" tabindex="-1">交易品类说明 <a class="header-anchor" href="#交易品类说明" aria-label="Permalink to &quot;交易品类说明&quot;">​</a></h1><p>本页说明平台提供的各类交易玩法<strong>分别是什么、面向什么用户</strong>。是否对用户开放由「基础配置 → 玩法配置」控制。</p><h2 id="现货-币币交易" tabindex="-1">现货（币币交易） <a class="header-anchor" href="#现货-币币交易" aria-label="Permalink to &quot;现货（币币交易）&quot;">​</a></h2><p>最基础的交易形式：用一种资产买卖另一种资产。</p><ul><li>支持限价委托与市价委托</li><li>交易对与手续费在后台「币种管理」中配置</li><li>面向：有明确买卖意图的用户</li></ul><h3 id="人工强制成交-运营功能" tabindex="-1">人工强制成交（运营功能） <a class="header-anchor" href="#人工强制成交-运营功能" aria-label="Permalink to &quot;人工强制成交（运营功能）&quot;">​</a></h3><p>限价委托需要等行情到达委托价才会成交，行情长期不到位时订单会一直挂着。 运营可在后台「币币交易订单」列表中，对<strong>待成交</strong>的限价单执行「强制成交」。</p><ul><li>按该订单的<strong>委托价格</strong>全额成交，不参考当前行情</li><li>手续费照常收取，用户端看到的成交记录与正常成交完全一致</li><li>仅对「待成交」状态的订单可用；已成交、已撤销的订单不会出现该按钮</li><li>每次操作都会记入「操作日志」，可追溯操作人与时间</li><li>外汇、黄金、股票、指数等 TradFi 标的与现货共用同一套委托机制，同样适用</li></ul><div class="warning custom-block"><p class="custom-block-title">该操作不可撤销</p><p>强制成交会立即扣款、到账并写入资金流水，执行后无法回退，请先核对订单信息。 需要「强制成交」权限，可在「角色管理」中按角色授予。</p></div><h2 id="闪兑" tabindex="-1">闪兑 <a class="header-anchor" href="#闪兑" aria-label="Permalink to &quot;闪兑&quot;">​</a></h2><p>两种资产之间按当前价格<strong>直接兑换</strong>，不需要挂单等待成交。</p><ul><li>操作简单，一步完成</li><li>面向：只想换币、不关心挂单价格的用户</li></ul><h2 id="秒合约" tabindex="-1">秒合约 <a class="header-anchor" href="#秒合约" aria-label="Permalink to &quot;秒合约&quot;">​</a></h2><p>在<strong>短周期内</strong>判断价格涨跌方向，到期按结果结算。</p><ul><li>周期短、规则简单</li><li>后台可配置周期与结算参数</li><li>面向：偏好轻量玩法的用户</li></ul><h2 id="u-本位永续合约" tabindex="-1">U 本位永续合约 <a class="header-anchor" href="#u-本位永续合约" aria-label="Permalink to &quot;U 本位永续合约&quot;">​</a></h2><p>带杠杆的双向交易，可做多也可做空。</p><ul><li>支持杠杆倍数选择</li><li>支持止盈止损</li><li>保证金不足时触发<strong>强制平仓</strong></li><li>面向：有交易经验的用户</li></ul><div class="tip custom-block"><p class="custom-block-title">结算的确定性</p><p>系统对合约清算做了专项加固：行情链路中断时，陈旧报价会被识别并拒绝采信，系统主动暂停该标的的清算与条件单触发，待行情恢复后按真实市价重新判定。同一笔仓位只会被结算一次，不会重复出入金。</p></div><h2 id="tradfi-传统金融标的" tabindex="-1">TradFi 传统金融标的 <a class="header-anchor" href="#tradfi-传统金融标的" aria-label="Permalink to &quot;TradFi 传统金融标的&quot;">​</a></h2><p>除数字资产外，平台还提供<strong>外汇、商品、股票、指数、港股</strong>等传统金融标的的行情与交易。</p><ul><li>行情来自第三方行情源，在后台配置</li><li>以外币计价的标的（如港股、A 股）按后台配置的汇率换算</li><li><strong>休市时间</strong>：传统金融市场有开收盘时间，休市期间不可交易，系统会有相应提示</li></ul><div class="danger custom-block"><p class="custom-block-title">汇率配置</p><p>汇率配置错误会导致以外币计价的所有标的成交价按错误比例偏移。该配置为<strong>超级管理员专属</strong>，修改需格外谨慎。</p></div><h2 id="跟单交易" tabindex="-1">跟单交易 <a class="header-anchor" href="#跟单交易" aria-label="Permalink to &quot;跟单交易&quot;">​</a></h2><p>见 <a href="/CoinExchange/zh/guide/follow">跟单交易</a>。</p><h2 id="平台自发币与做市" tabindex="-1">平台自发币与做市 <a class="header-anchor" href="#平台自发币与做市" aria-label="Permalink to &quot;平台自发币与做市&quot;">​</a></h2><p>平台可以发行自己的币种（后台「自发币」），并绑定给指定的做市商账号管理（见<a href="/CoinExchange/zh/guide/market-maker">做市商端</a>）；自发币还可在币种配置里作为<strong>手续费抵扣币</strong>，按折扣系数抵扣现货手续费。</p><h2 id="申购-打新" tabindex="-1">申购（打新） <a class="header-anchor" href="#申购-打新" aria-label="Permalink to &quot;申购（打新）&quot;">​</a></h2><p>新币认购玩法，项目在后台经历「筹备中 → 订阅 → 审批 → 进行中 → 发行」的状态流转。</p><div class="warning custom-block"><p class="custom-block-title">配置提醒</p><p>创建申购项目时，<strong>「购买上限」必须填写</strong>，留空可能导致用户端下单异常。</p></div>',30)])])}const g=l(e,[["render",o]]);export{p as __pageData,g as default};
